import mapData from "./geoMap.json";

/**
 * US state outlines and one point per DMA, in an Albers USA frame (975x610), for the Geo
 * Footprint map. Generated by buildGeoMap.ts; never hand-edit the JSON.
 */
export interface MapState {
  code: string;
  /** SVG path data. */
  d: string;
  /** [minX, minY, maxX, maxY] in map units. */
  bbox: [number, number, number, number];
}

export interface MapMarket {
  /** USPS code of the state the market's principal city is in. */
  state: string;
  x: number;
  y: number;
}

export const MAP_VIEWBOX = mapData.viewBox as [number, number, number, number];
export const MAP_STATES = mapData.states as MapState[];
export const MAP_MARKETS = mapData.markets as Record<string, MapMarket>;
export const MAP_SOURCE_LABEL: string = mapData.source;

const byCode = new Map(MAP_STATES.map((state) => [state.code, state]));

/**
 * The window onto the map that frames a footprint: its states with a margin, widened to the
 * map's own aspect ratio so nothing stretches, and never zoomed in past a quarter of the country
 * so a single small state still shows its neighbours. The whole map when nothing is given.
 */
export function footprintViewBox(stateCodes: string[]): [number, number, number, number] {
  const boxes = stateCodes.map((code) => byCode.get(code)?.bbox).filter((box): box is MapState["bbox"] => Boolean(box));
  if (boxes.length === 0) return MAP_VIEWBOX;
  const [, , fullWidth, fullHeight] = MAP_VIEWBOX;
  const aspect = fullWidth / fullHeight;

  let minX = Math.min(...boxes.map((box) => box[0]));
  let minY = Math.min(...boxes.map((box) => box[1]));
  let width = Math.max(...boxes.map((box) => box[2])) - minX;
  let height = Math.max(...boxes.map((box) => box[3])) - minY;
  const margin = Math.max(width, height) * 0.15;
  minX -= margin;
  minY -= margin;
  width += margin * 2;
  height += margin * 2;

  const minWidth = fullWidth / 4;
  if (width < minWidth) { minX -= (minWidth - width) / 2; width = minWidth; }
  if (width / height < aspect) { const grown = height * aspect; minX -= (grown - width) / 2; width = grown; }
  else { const grown = width / aspect; minY -= (grown - height) / 2; height = grown; }

  // A footprint spanning most of the country reads better as the whole map.
  if (width >= fullWidth * 0.8) return MAP_VIEWBOX;
  const round = (value: number) => Math.round(value * 10) / 10;
  return [round(minX), round(minY), round(width), round(height)];
}
